def test_frontend_const_const_pipeline_runtime():
    """Frontend 2*3 is constant-folded to 6 by the frontend; pipeline tiles the map."""
    sdfg = frontend_const_const_program.to_sdfg(simplify=True)
    count = apply_cutile_pipeline(
        sdfg,
        validate=True,
        apply_map_tiling=True,
        tile_shape=(6, 5),
    )
    assert count >= 1

    sdfg.expand_library_nodes()
    sdfg.validate()

    c = np.zeros((24, 20), dtype=np.float64)
    sdfg(C=c)
    np.testing.assert_allclose(c, np.full((24, 20), 6.0), rtol=0.0, atol=1e-12)


